          'CAD': 0.015, 'AUD': 0.016, 'CHF': 0.011, 'CNY': 0.085, 'KRW': 15.3
        }
      };

      const rates = fallbackRates[baseCurrency] || fallbackRates['USD'];

      res.json(
        createResponse(true, {
          base: baseCurrency,
          rates,
          date: new Date().toISOString().split('T')[0],
          source: "fallback"
        }, "Exchange rates retrieved successfully (fallback)")
