import { useState } from 'react';
import { motion } from 'framer-motion';
import { FolderOpen, Upload, Download, Trash2, FileText, Image, Eye, Plus, Grid, List } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';

interface Document {
  id: string;
  name: string;
  type: string;
  category: string;
  uploadDate: string;
  size: string;
  url?: string;
}

export default function DocumentWallet() {
  const [documents, setDocuments] = useState<Document[]>([
    {
      id: '1',
      name: 'Passport_US_2024.pdf',
      type: 'pdf',
      category: 'passport',
      uploadDate: '2024-01-15',
      size: '2.3 MB',
      url: '#'
    },
    {
      id: '2',
      name: 'Travel_Insurance_Policy.pdf',
      type: 'pdf',
      category: 'insurance',
      uploadDate: '2024-01-10',
      size: '1.8 MB',
      url: '#'
    },
    {
      id: '3',
      name: 'Visa_Japan_Photo.jpg',
      type: 'image',
      category: 'visa',
      uploadDate: '2024-01-08',
      size: '0.9 MB',
      url: '#'
    }
  ]);
  const [viewMode, setViewMode] = useState<'grid' | 'list'>('grid');
  const [selectedCategory, setSelectedCategory] = useState('all');
  const [isDragOver, setIsDragOver] = useState(false);

  const categories = [
    { value: 'all', label: 'All Documents' },
    { value: 'passport', label: 'Passport' },
    { value: 'visa', label: 'Visa' },
    { value: 'insurance', label: 'Insurance' },
    { value: 'ticket', label: 'Tickets' },
    { value: 'hotel', label: 'Hotel Bookings' },
    { value: 'other', label: 'Other' }
  ];

  const filteredDocuments = selectedCategory === 'all' 
    ? documents 
    : documents.filter(doc => doc.category === selectedCategory);

  const handleFileUpload = (files: FileList | null) => {
    if (!files) return;

    Array.from(files).forEach(file => {
      const newDoc: Document = {
        id: Date.now().toString() + Math.random().toString(36).substr(2, 9),
        name: file.name,
        type: file.type.includes('image') ? 'image' : 'pdf',
        category: 'other',
        uploadDate: new Date().toISOString().split('T')[0],
        size: `${(file.size / (1024 * 1024)).toFixed(1)} MB`,
        url: URL.createObjectURL(file)
      };

      setDocuments(prev => [...prev, newDoc]);
    });
  };

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragOver(true);
  };

  const handleDragLeave = () => {
    setIsDragOver(false);
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragOver(false);
    handleFileUpload(e.dataTransfer.files);
  };

  const deleteDocument = (id: string) => {
    setDocuments(prev => prev.filter(doc => doc.id !== id));
  };

  const getDocumentIcon = (type: string) => {
    return type === 'image' ? Image : FileText;
  };

  const getCategoryIcon = (category: string) => {
    const icons = {
      passport: '🛂',
      visa: '📋',
      insurance: '🛡️',
      ticket: '🎫',
      hotel: '🏨',
      other: '📄'
    };
    return icons[category as keyof typeof icons] || '📄';
  };

  return (
    <div className="min-h-screen bg-background py-12">
      <div className="container mx-auto px-6">
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.6 }}
          className="text-center mb-12"
        >
          <div className="w-16 h-16 bg-primary/10 dark:bg-primary/20 rounded-2xl flex items-center justify-center mx-auto mb-6">
            <FolderOpen className="w-8 h-8 text-primary" />
          </div>
          <h1 className="text-display mb-4">Travel Document Wallet</h1>
          <p className="text-body text-muted-foreground max-w-2xl mx-auto">
            Securely store and organize all your travel documents in one place. Upload passports, visas, insurance, and tickets.
          </p>
        </motion.div>

        <div className="max-w-6xl mx-auto space-y-8">
          {/* Upload Zone */}
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.6, delay: 0.1 }}
          >
            <Card className="shadow-elegant-lg border-0">
              <CardContent className="p-8">
                <div
                  className={`border-2 border-dashed rounded-xl p-8 text-center transition-colors ${
                    isDragOver 
                      ? 'border-primary bg-primary/5' 
                      : 'border-muted-foreground/20 hover:border-primary/50'
                  }`}
                  onDragOver={handleDragOver}
                  onDragLeave={handleDragLeave}
                  onDrop={handleDrop}
                >
                  <Upload className="w-12 h-12 text-muted-foreground mx-auto mb-4" />
                  <h3 className="text-lg font-semibold mb-2">Upload Documents</h3>
                  <p className="text-muted-foreground mb-4">
                    Drag and drop files here or click to browse
                  </p>
                  <button 
                    onClick={() => document.getElementById('file-upload')?.click()}
                    className="bg-black text-white dark:bg-white dark:text-black hover:opacity-90 px-4 py-2 rounded-md font-semibold shadow-sm transition-all duration-300 flex items-center space-x-2"
                    aria-label="Upload travel documents"
                  >
                    <Plus className="w-4 h-4" />
                    <span>Upload Document</span>
                  </button>
                  <input
                    id="file-upload"
                    type="file"
                    multiple
                    accept=".pdf,.jpg,.jpeg,.png"
                    className="hidden"
                    onChange={(e) => handleFileUpload(e.target.files)}
                  />
                  <p className="text-xs text-muted-foreground mt-2">
                    Supports PDF, JPG, PNG files up to 10MB each
                  </p>
                </div>
              </CardContent>
            </Card>
          </motion.div>

          {/* Controls */}
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.6, delay: 0.2 }}
            className="flex flex-col sm:flex-row justify-between items-start sm:items-center space-y-4 sm:space-y-0"
          >
            <div className="flex items-center space-x-4">
              <Select value={selectedCategory} onValueChange={setSelectedCategory}>
                <SelectTrigger className="w-48">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  {categories.map(category => (
                    <SelectItem key={category.value} value={category.value}>
                      {category.label}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>

              <span className="text-sm text-muted-foreground">
                {filteredDocuments.length} document{filteredDocuments.length !== 1 ? 's' : ''}
              </span>
            </div>

            <div className="flex items-center space-x-2">
              <Button
                variant={viewMode === 'grid' ? 'default' : 'outline'}
                size="sm"
                onClick={() => setViewMode('grid')}
              >
                <Grid className="w-4 h-4" />
              </Button>
              <Button
                variant={viewMode === 'list' ? 'default' : 'outline'}
                size="sm"
                onClick={() => setViewMode('list')}
              >
                <List className="w-4 h-4" />
              </Button>
            </div>
          </motion.div>

          {/* Documents */}
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.6, delay: 0.3 }}
          >
            {filteredDocuments.length > 0 ? (
              <div className={viewMode === 'grid' ? 'grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6' : 'space-y-4'}>
                {filteredDocuments.map((doc, index) => {
                  const IconComponent = getDocumentIcon(doc.type);

                  return (
                    <motion.div
                      key={doc.id}
                      initial={{ opacity: 0, y: 20 }}
                      animate={{ opacity: 1, y: 0 }}
                      transition={{ duration: 0.4, delay: index * 0.1 }}
                    >
                      <Card className={`shadow-elegant hover:shadow-elegant-lg transition-shadow border-0 ${
                        viewMode === 'list' ? 'p-4' : ''
                      }`}>
                        <CardContent className={viewMode === 'grid' ? 'p-6' : 'p-0'}>
                          <div className={`flex ${viewMode === 'grid' ? 'flex-col space-y-4' : 'items-center space-x-4'}`}>
                            {/* Document Preview */}
                            <div className={`${
                              viewMode === 'grid' 
                                ? 'w-full h-32 bg-muted/50 rounded-lg flex items-center justify-center' 
                                : 'w-12 h-12 bg-muted/50 rounded-lg flex items-center justify-center flex-shrink-0'
                            }`}>
                              <span className="text-2xl">{getCategoryIcon(doc.category)}</span>
                            </div>

                            {/* Document Info */}
                            <div className={`${viewMode === 'grid' ? 'space-y-2' : 'flex-1 min-w-0'}`}>
                              <h3 className={`font-semibold ${viewMode === 'list' ? 'truncate' : ''}`}>
                                {doc.name}
                              </h3>
                              <div className={`text-sm text-muted-foreground ${
                                viewMode === 'grid' ? 'space-y-1' : 'flex items-center space-x-4'
                              }`}>
                                <span>Uploaded {doc.uploadDate}</span>
                                <span className={viewMode === 'list' ? '' : 'block'}>Size: {doc.size}</span>
                              </div>
                            </div>

                            {/* Actions */}
                            <div className={`flex ${
                              viewMode === 'grid' ? 'justify-center space-x-2' : 'space-x-2'
                            }`}>
                              <Button variant="outline" size="sm">
                                <Eye className="w-4 h-4" />
                                {viewMode === 'grid' && <span className="ml-2">View</span>}
                              </Button>
                              <Button variant="outline" size="sm">
                                <Download className="w-4 h-4" />
                                {viewMode === 'grid' && <span className="ml-2">Download</span>}
                              </Button>
                              <Button 
                                variant="outline" 
                                size="sm"
                                onClick={() => deleteDocument(doc.id)}
                                className="text-destructive hover:text-destructive"
                              >
                                <Trash2 className="w-4 h-4" />
                                {viewMode === 'grid' && <span className="ml-2">Delete</span>}
                              </Button>
                            </div>
                          </div>
                        </CardContent>
                      </Card>
                    </motion.div>
                  );
                })}
              </div>
            ) : (
              <Card className="shadow-elegant-lg border-0">
                <CardContent className="p-12 text-center">
                  <FolderOpen className="w-16 h-16 text-muted-foreground mx-auto mb-4" />
                  <h3 className="text-lg font-semibold mb-2">No Documents Found</h3>
                  <p className="text-muted-foreground mb-4">
                    {selectedCategory === 'all' 
                      ? 'Upload your first travel document to get started'
                      : `No documents found in the ${categories.find(c => c.value === selectedCategory)?.label} category`
                    }
                  </p>
                  <button 
                    onClick={() => document.getElementById('file-upload')?.click()}
                    className="bg-black text-white dark:bg-white dark:text-black hover:opacity-90 px-4 py-2 rounded-md font-semibold shadow-sm transition-all duration-300"
                    aria-label="Upload your first travel document"
                  >
                    Upload Document
                  </button>
                </CardContent>
              </Card>
            )}
          </motion.div>
        </div>
      </div>
    </div>
  );
}

client/src/pages/ExpenseEstimator.tsx.content:
import { useState } from 'react';
import { motion } from 'framer-motion';
import { Calculator, DollarSign, Plane, MapPin, Users, Calendar, Hotel, Utensils, Camera } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';

interface CostBreakdown {
  transport: number;
  hotel: number;
  food: number;
  activities: number;
  total: number;
}

export default function ExpenseEstimator() {
  const [formData, setFormData] = useState({
    from: '',
    to: '',
    days: '',
    travelers: ''
  });
  const [breakdown, setBreakdown] = useState<CostBreakdown | null>(null);
  const [isCalculating, setIsCalculating] = useState(false);

  const handleInputChange = (field: string, value: string) => {
    setFormData(prev => ({ ...prev, [field]: value }));
  };

  const calculateEstimate = () => {
    if (!formData.from || !formData.to || !formData.days || !formData.travelers) {
      return;
    }

    setIsCalculating(true);

    // Simulate calculation
    setTimeout(() => {
      const days = parseInt(formData.days);
      const travelers = parseInt(formData.travelers);

      // Base costs per person per day
      const baseCosts = {
        transport: 150 + Math.random() * 300,
        hotel: 80 + Math.random() * 200,
        food: 40 + Math.random() * 60,
        activities: 30 + Math.random() * 70
      };

      const calculated = {
        transport: Math.round(baseCosts.transport * travelers),
        hotel: Math.round(baseCosts.hotel * days * travelers),
        food: Math.round(baseCosts.food * days * travelers),
        activities: Math.round(baseCosts.activities * days * travelers),
        total: 0
      };

      calculated.total = calculated.transport + calculated.hotel + calculated.food + calculated.activities;

      setBreakdown(calculated);
      setIsCalculating(false);
    }, 2000);
  };

  return (
    <div className="min-h-screen bg-background py-12">
      <div className="container mx-auto px-6">
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.6 }}
          className="text-center mb-12"
        >
          <div className="w-16 h-16 bg-primary/10 dark:bg-primary/20 rounded-2xl flex items-center justify-center mx-auto mb-6">
            <Calculator className="w-8 h-8 text-primary" />
          </div>
          <h1 className="text-display mb-4">Travel Expense Estimator</h1>
          <p className="text-body text-muted-foreground max-w-2xl mx-auto">
            Get a detailed breakdown of your travel costs including transport, accommodation, food, and activities.
          </p>
        </motion.div>

        <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 max-w-6xl mx-auto">
          {/* Input Form */}
          <motion.div
            initial={{ opacity: 0, x: -20 }}
            animate={{ opacity: 1, x: 0 }}
            transition={{ duration: 0.6, delay: 0.1 }}
          >
            <Card className="shadow-elegant-lg border-0">
              <CardHeader>
                <CardTitle className="flex items-center space-x-2">
                  <MapPin className="w-5 h-5" />
                  <span>Trip Details</span>
                </CardTitle>
              </CardHeader>
              <CardContent className="space-y-6">
                <div className="space-y-2">
                  <Label htmlFor="from">From</Label>
                  <Input
                    id="from"
                    placeholder="Enter departure city"
                    value={formData.from}
                    onChange={(e) => handleInputChange('from', e.target.value)}
                  />
                </div>

                <div className="space-y-2">
                  <Label htmlFor="to">To</Label>
                  <Input
                    id="to"
                    placeholder="Enter destination city"
                    value={formData.to}
                    onChange={(e) => handleInputChange('to', e.target.value)}
                  />
                </div>

                <div className="grid grid-cols-2 gap-4">
                  <div className="space-y-2">
                    <Label htmlFor="days">Days</Label>
                    <Select onValueChange={(value) => handleInputChange('days', value)}>
                      <SelectTrigger>
                        <SelectValue placeholder="Select days" />
                      </SelectTrigger>
                      <SelectContent>
                        {[...Array(30)].map((_, i) => (
                          <SelectItem key={i + 1} value={(i + 1).toString()}>
                            {i + 1} {i + 1 === 1 ? 'day' : 'days'}
                          </SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                  </div>

                  <div className="space-y-2">
                    <Label htmlFor="travelers">Travelers</Label>
                    <Select onValueChange={(value) => handleInputChange('travelers', value)}>
                      <SelectTrigger>
                        <SelectValue placeholder="Select travelers" />
                      </SelectTrigger>
                      <SelectContent>
                        {[...Array(10)].map((_, i) => (
                          <SelectItem key={i + 1} value={(i + 1).toString()}>
                            {i + 1} {i + 1 === 1 ? 'person' : 'people'}
                          </SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                  </div>
                </div>

                <Button
                  onClick={calculateEstimate}
                  disabled={!formData.from || !formData.to || !formData.days || !formData.travelers || isCalculating}
                  className="w-full bg-black text-white dark:bg-white dark:text-black hover:opacity-90 px-4 py-2 rounded-md font-semibold shadow-sm transition"
                  aria-label="Explore this tool"
                >
                  {isCalculating ? 'Calculating...' : 'Calculate Estimate'}
                </Button>
              </CardContent>
            </Card>
          </motion.div>

          {/* Results */}
          <motion.div
            initial={{ opacity: 0, x: 20 }}
            animate={{ opacity: 1, x: 0 }}
            transition={{ duration: 0.6, delay: 0.2 }}
          >
            <Card className="shadow-elegant-lg border-0">
              <CardHeader>
                <CardTitle className="flex items-center space-x-2">
                  <DollarSign className="w-5 h-5" />
                  <span>Cost Breakdown</span>
                </CardTitle>
              </CardHeader>
              <CardContent>
                {breakdown ? (
                  <div className="space-y-4">
                    <div className="grid grid-cols-2 gap-4">
                      <div className="flex items-center justify-between p-4 bg-muted/50 rounded-lg">
                        <div className="flex items-center space-x-2">
                          <Plane className="w-4 h-4 text-muted-foreground" />
                          <span className="text-sm">Transport</span>
                        </div>
                        <span className="font-semibold">${breakdown.transport.toLocaleString()}</span>
                      </div>

                      <div className="flex items-center justify-between p-4 bg-muted/50 rounded-lg">
                        <div className="flex items-center space-x-2">
                          <Hotel className="w-4 h-4 text-muted-foreground" />
                          <span className="text-sm">Hotel</span>
                        </div>
                        <span className="font-semibold">${breakdown.hotel.toLocaleString()}</span>
                      </div>

                      <div className="flex items-center justify-between p-4 bg-muted/50 rounded-lg">
                        <div className="flex items-center space-x-2">
                          <Utensils className="w-4 h-4 text-muted-foreground" />
                          <span className="text-sm">Food</span>
                        </div>
                        <span className="font-semibold">${breakdown.food.toLocaleString()}</span>
                      </div>

                      <div className="flex items-center justify-between p-4 bg-muted/50 rounded-lg">
                        <div className="flex items-center space-x-2">
                          <Camera className="w-4 h-4 text-muted-foreground" />
                          <span className="text-sm">Activities</span>
                        </div>
                        <span className="font-semibold">${breakdown.activities.toLocaleString()}</span>
                      </div>
                    </div>

                    <div className="border-t pt-4">
                      <div className="flex items-center justify-between p-4 bg-primary/10 dark:bg-primary/20 rounded-lg">
                        <span className="text-lg font-semibold">Total Estimated Cost</span>
                        <span className="text-2xl font-bold text-primary">${breakdown.total.toLocaleString()}</span>
                      </div>
                    </div>

                    <div className="text-xs text-muted-foreground text-center">
                      * Estimates are based on average costs and may vary based on season, preferences, and availability.
                    </div>
                  </div>
                ) : (
                  <div className="text-center py-12">
                    <Calculator className="w-12 h-12 text-muted-foreground mx-auto mb-4" />
                    <p className="text-muted-foreground">
                      Fill in your trip details to get a cost breakdown
                    </p>
                  </div>
                )}
              </CardContent>
            </Card>
          </motion.div>
        </div>
      </div>
    </div>
  );
}

client/src/pages/ExploreGuide.tsx.content:
import { useState } from 'react';
import { Navigation, MapPin, Clock, Cloud, ChevronDown, ChevronUp, Route } from 'lucide-react';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Collapsible, CollapsibleContent, CollapsibleTrigger } from "@/components/ui/collapsible";
import { toast } from "@/hooks/use-toast";

const ExploreGuide = () => {
  const [selectedCity, setSelectedCity] = useState('');
  const [fromLocation, setFromLocation] = useState('');
  const [toLocation, setToLocation] = useState('');
  const [expandedTips, setExpandedTips] = useState<{ [key: string]: boolean }>({});

  const handleUseMyLocation = () => {
    if (navigator.geolocation) {
      navigator.geolocation.getCurrentPosition(
        (position) => {
          // Mock city detection based on coordinates
          setSelectedCity("Current Location (San Francisco)");
          toast({
            title: "Location Found",
            description: "Using your current location for recommendations."
          });
        },
        (error) => {
          toast({
            title: "Location Error",
            description: "Unable to access your location. Please enter manually.",
            variant: "destructive"
          });
        }
      );
    } else {
      toast({
        title: "Location Not Supported",
        description: "Geolocation is not supported by your browser.",
        variant: "destructive"
      });
    }
  };

  const handleFindRoute = () => {
    if (!fromLocation || !toLocation) {
      toast({
        title: "Missing Information",
        description: "Please enter both from and to locations.",
        variant: "destructive"
      });
      return;
    }

    toast({
      title: "Route Found",
      description: `Route from ${fromLocation} to ${toLocation} calculated.`
    });
  };

  const toggleTip = (tipId: string) => {
    setExpandedTips(prev => ({
      ...prev,
      [tipId]: !prev[tipId]
    }));
  };

  const recommendedPlaces = [
    {
      name: "Golden Gate Bridge",
      type: "Landmark",
      rating: 4.8,
      description: "Iconic suspension bridge with stunning views"
    },
    {
      name: "Fisherman's Wharf",
      type: "Attraction",
      rating: 4.5,
      description: "Historic waterfront district with shops and restaurants"
    },
    {
      name: "Alcatraz Island",
      type: "Historical Site",
      rating: 4.7,
      description: "Former federal prison with guided tours"
    },
    {
      name: "Union Square",
      type: "Shopping",
      rating: 4.3,
      description: "Premier shopping and dining destination"
    }
  ];

  const localTips = [
    {
      id: "transport",
      title: "Transportation Tips",
      content: "Use Muni for public transport. Cable cars are tourist attractions but slower for commuting. Uber/Lyft are convenient but can be expensive during peak hours."
    },
    {
      id: "dining",
      title: "Local Dining",
      content: "Try Mission District for authentic Mexican food, Chinatown for dim sum, and North Beach for Italian cuisine. Make reservations for popular restaurants."
    },
    {
      id: "safety",
      title: "Safety & Etiquette",
      content: "Avoid leaving items visible in cars. Dress in layers as weather changes quickly. Be respectful of homeless individuals and keep personal belongings secure."
    },
    {
      id: "timing",
      title: "Best Times to Visit",
      content: "Visit popular attractions early morning or late afternoon to avoid crowds. Summer evenings can be foggy and cold. September-October offers the best weather."
    }
  ];

  return (
    <div className="min-h-screen bg-background">
      <div className="container mx-auto px-4 py-16">
        {/* Header */}
        <div className="text-center mb-12">
          <div className="w-16 h-16 mx-auto mb-6 rounded-full bg-muted flex items-center justify-center">
            <Navigation className="w-8 h-8 text-foreground" />
          </div>
          <h1 className="text-4xl md:text-5xl font-bold text-foreground mb-4">
            Explore Guide
          </h1>
          <p className="text-xl text-muted-foreground max-w-2xl mx-auto">
            Your smart travel companion — get local routes, places to visit, and tips based on your current location.
          </p>
        </div>

        {/* Location Input */}
        <div className="max-w-4xl mx-auto mb-8">
          <Card className="border border-border bg-card">
            <CardHeader>
              <CardTitle className="text-xl text-card-foreground">Select Your Location</CardTitle>
            </CardHeader>
            <CardContent>
              <div className="flex flex-col sm:flex-row gap-4">
                <Input
                  placeholder="Enter city or destination..."
                  value={selectedCity}
                  onChange={(e) => setSelectedCity(e.target.value)}
                  className="flex-1"
                  aria-label="Enter city or destination"
                />
                <Button
                  onClick={handleUseMyLocation}
                  variant="outline"
                  className="bg-foreground text-background hover:opacity-90 font-semibold transition"
                  aria-label="Use my current location"
                >
                  <MapPin className="w-4 h-4 mr-2" />
                  Use My Location
                </Button>
              </div>
            </CardContent>
          </Card>
        </div>

        <div className="max-w-6xl mx-auto grid grid-cols-1 lg:grid-cols-3 gap-8">
          {/* Main Content */}
          <div className="lg:col-span-2 space-y-8">
            {/* Recommended Places */}
            <Card className="border border-border bg-card">
              <CardHeader>
                <CardTitle className="text-xl text-card-foreground">Recommended Places</CardTitle>
                <CardDescription>
                  Popular attractions and hidden gems in your area
                </CardDescription>
              </CardHeader>
              <CardContent>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  {recommendedPlaces.map((place, index) => (
                    <Card key={index} className="border border-border/50">
                      <CardContent className="p-4">
                        <div className="flex justify-between items-start mb-2">
                          <h3 className="font-semibold text-card-foreground">{place.name}</h3>
                          <span className="text-sm text-muted-foreground">★ {place.rating}</span>
                        </div>
                        <p className="text-sm text-primary mb-2">{place.type}</p>
                        <p className="text-sm text-muted-foreground">{place.description}</p>
                      </CardContent>
                    </Card>
                  ))}
                </div>
              </CardContent>
            </Card>

            {/* Route Planner */}
            <Card className="border border-border bg-card">
              <CardHeader>
                <CardTitle className="text-xl text-card-foreground flex items-center gap-2">
                  <Route className="w-5 h-5" />
                  Route Planner
                </CardTitle>
                <CardDescription>
                  Find the best route between two locations
                </CardDescription>
              </CardHeader>
              <CardContent className="space-y-4">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  <div className="space-y-2">
                    <label className="text-sm font-medium text-foreground" htmlFor="from-location">
                      From
                    </label>
                    <Input
                      id="from-location"
                      placeholder="Starting location..."
                      value={fromLocation}
                      onChange={(e) => setFromLocation(e.target.value)}
                      aria-label="Starting location"
                    />
                  </div>
                  <div className="space-y-2">
                    <label className="text-sm font-medium text-foreground" htmlFor="to-location">
                      To
                    </label>
                    <Input
                      id="to-location"
                      placeholder="Destination..."
                      value={toLocation}
                      onChange={(e) => setToLocation(e.target.value)}
                      aria-label="Destination"
                    />
                  </div>
                </div>
                <Button
                  onClick={handleFindRoute}
                  className="w-full bg-foreground text-background hover:opacity-90 font-semibold transition"
                  aria-label="Find route"
                >
                  Find Route
                </Button>
              </CardContent>
            </Card>

            {/* Local Tips */}
            <Card className="border border-border bg-card">
              <CardHeader>
                <CardTitle className="text-xl text-card-foreground">Local Tips</CardTitle>
                <CardDescription>
                  Insider knowledge from locals and experienced travelers
                </CardDescription>
              </CardHeader>
              <CardContent className="space-y-3">
                {localTips.map((tip) => (
                  <Collapsible key={tip.id} open={expandedTips[tip.id]} onOpenChange={() => toggleTip(tip.id)}>
                    <CollapsibleTrigger asChild>
                      <Button
                        variant="outline"
                        className="w-full justify-between text-left"
                        aria-label={`Toggle ${tip.title}`}
                      >
                        <span className="font-medium">{tip.title}</span>
                        {expandedTips[tip.id] ? (
                          <ChevronUp className="w-4 h-4" />
                        ) : (
                          <ChevronDown className="w-4 h-4" />
                        )}
                      </Button>
                    </CollapsibleTrigger>
                    <CollapsibleContent className="pt-3 px-4 pb-2">
                      <p className="text-sm text-muted-foreground leading-relaxed">
                        {tip.content}
                      </p>
                    </CollapsibleContent>
                  </Collapsible>
                ))}
              </CardContent>
            </Card>
          </div>

          {/* Sidebar */}
          <div className="space-y-6">
            {/* Weather Widget */}
            <Card className="border border-border bg-card">
              <CardHeader className="pb-3">
                <CardTitle className="text-lg text-card-foreground flex items-center gap-2">
                  <Cloud className="w-5 h-5" />
                  Current Weather
                </CardTitle>
              </CardHeader>
              <CardContent>
                <div className="text-center">
                  <div className="text-3xl font-bold text-foreground mb-2">72°F</div>
                  <p className="text-muted-foreground mb-4">Partly Cloudy</p>
                  <div className="grid grid-cols-2 gap-4 text-sm">
                    <div>
                      <p className="text-muted-foreground">High</p>
                      <p className="font-semibold text-foreground">75°F</p>
                    </div>
                    <div>
                      <p className="text-muted-foreground">Low</p>
                      <p className="font-semibold text-foreground">65°F</p>
                    </div>
                  </div>
                </div>
              </CardContent>
            </Card>

            {/* Quick Actions */}
            <Card className="border border-border bg-card">
              <CardHeader className="pb-3">
                <CardTitle className="text-lg text-card-foreground">Quick Actions</CardTitle>
              </CardHeader>
              <CardContent className="space-y-3">
                <Button
                  variant="outline"
                  className="w-full justify-start"
                  aria-label="Find nearby restaurants"
                >
                  <Clock className="w-4 h-4 mr-2" />
                  Nearby Restaurants
                </Button>
                <Button
                  variant="outline"
                  className="w-full justify-start"
                  aria-label="Find ATMs"
                >
                  <MapPin className="w-4 h-4 mr-2" />
                  Find ATMs
                </Button>
                <Button
                  variant="outline"
                  className="w-full justify-start"
                  aria-label="Emergency contacts"
                >
                  <Navigation className="w-4 h-4 mr-2" />
                  Emergency Contacts
                </Button>
              </CardContent>
            </Card>
          </div>
        </div>
      </div>
    </div>
  );
};

export default ExploreGuide;

