import { useState } from 'react';
import { motion } from 'framer-motion';
import { MapPin, Plane, Train, Car, Clock, DollarSign } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';

interface RouteOption {
  type: 'flight' | 'train' | 'road';
  duration: string;
  cost: string;
  details: string;
  emissions: string;
  icon: React.ElementType;
}

interface RouteResults {
  distance: string;
  options: RouteOption[];
}

export default function RouteFinder() {
  const [origin, setOrigin] = useState('');
  const [destination, setDestination] = useState('');
  const [results, setResults] = useState<RouteResults | null>(null);
  const [isSearching, setIsSearching] = useState(false);

  const findRoute = () => {
    if (!origin || !destination) return;

    setIsSearching(true);

    // Simulate API call
    setTimeout(() => {
      const mockResults: RouteResults = {
        distance: `${Math.floor(Math.random() * 2000 + 500)} km`,
        options: [
          {
            type: 'flight',
            duration: `${Math.floor(Math.random() * 8 + 2)}h ${Math.floor(Math.random() * 60)}m`,
            cost: `$${Math.floor(Math.random() * 500 + 200)}`,
            details: 'Direct flight • 1 stop • Multiple airlines available',
            emissions: `${Math.floor(Math.random() * 200 + 100)} kg CO₂`,
            icon: Plane
          },
          {
            type: 'train',
            duration: `${Math.floor(Math.random() * 12 + 8)}h ${Math.floor(Math.random() * 60)}m`,
            cost: `$${Math.floor(Math.random() * 200 + 80)}`,
            details: 'High-speed rail • Scenic route • Station to station',
            emissions: `${Math.floor(Math.random() * 50 + 20)} kg CO₂`,
            icon: Train
          },
          {
            type: 'road',
            duration: `${Math.floor(Math.random() * 16 + 12)}h ${Math.floor(Math.random() * 60)}m`,
            cost: `$${Math.floor(Math.random() * 150 + 50)}`,
            details: 'Driving • Fuel + tolls • Rest stops recommended',
            emissions: `${Math.floor(Math.random() * 150 + 80)} kg CO₂`,
            icon: Car
          }
        ]
      };

      setResults(mockResults);
      setIsSearching(false);
    }, 2000);
  };

  const getRouteColor = (type: string) => {
    const colors = {
      flight: 'border-blue-500/20 bg-blue-500/10',
      train: 'border-green-500/20 bg-green-500/10',
      road: 'border-orange-500/20 bg-orange-500/10'
    };
    return colors[type as keyof typeof colors] || 'border-muted bg-muted/10';
  };

  const getRouteIconColor = (type: string) => {
    const colors = {
      flight: 'text-blue-500',
      train: 'text-green-500',
      road: 'text-orange-500'
    };
    return colors[type as keyof typeof colors] || 'text-muted-foreground';
  };

  return (
    <div className="min-h-screen bg-background py-12">
      <div className="container mx-auto px-6">
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.6 }}
          className="text-center mb-12"
        >
          <div className="w-16 h-16 bg-primary/10 dark:bg-primary/20 rounded-2xl flex items-center justify-center mx-auto mb-6">
            <MapPin className="w-8 h-8 text-primary" />
          </div>
          <h1 className="text-display mb-4">Route Finder</h1>
          <p className="text-body text-muted-foreground max-w-2xl mx-auto">
            Compare travel options between cities. Get time estimates, costs, and environmental impact for flights, trains, and road trips.
          </p>
        </motion.div>

        <div className="max-w-4xl mx-auto space-y-8">
          {/* Search Form */}
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.6, delay: 0.1 }}
          >
            <Card className="shadow-elegant-lg border-0">
              <CardHeader>
                <CardTitle className="flex items-center space-x-2">
                  <MapPin className="w-5 h-5" />
                  <span>Plan Your Route</span>
                </CardTitle>
              </CardHeader>
              <CardContent>
                <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                  <div className="space-y-2">
                    <Label htmlFor="origin">From</Label>
                    <Input
                      id="origin"
                      placeholder="Enter origin city"
                      value={origin}
                      onChange={(e) => setOrigin(e.target.value)}
                    />
                  </div>

                  <div className="space-y-2">
                    <Label htmlFor="destination">To</Label>
                    <Input
                      id="destination"
                      placeholder="Enter destination city"
                      value={destination}
                      onChange={(e) => setDestination(e.target.value)}
                    />
                  </div>

                  <div className="flex items-end">
                    <button
                      onClick={findRoute}
                      disabled={!origin || !destination || isSearching}
                      className="w-full bg-black text-white dark:bg-white dark:text-black hover:opacity-90 px-4 py-2 rounded-md font-semibold shadow-sm transition-all duration-300 disabled:opacity-50 disabled:cursor-not-allowed"
                      aria-label="Find travel routes between selected cities"
                    >
                      {isSearching ? 'Finding Routes...' : 'Find Route'}
                    </button>
                  </div>
                </div>
              </CardContent>
            </Card>
          </motion.div>

          {/* Route Map Placeholder */}
          {results && (
            <motion.div
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ duration: 0.6, delay: 0.2 }}
            >
              <Card className="shadow-elegant-lg border-0">
                <CardContent className="p-0">
                  <div className="h-64 bg-gradient-to-br from-muted/50 to-muted rounded-lg flex items-center justify-center relative overflow-hidden">
                    {/* Mock Map */}
                    <div className="absolute inset-0 opacity-10">
                      <div className="w-full h-full bg-[radial-gradient(circle_at_30%_30%,_rgba(0,0,0,0.1)_1px,_transparent_1px)] bg-[length:20px_20px]" />
                    </div>

                    <div className="text-center z-10">
                      <MapPin className="w-12 h-12 text-muted-foreground mx-auto mb-4" />
                      <p className="text-lg font-semibold">{origin} → {destination}</p>
                      <p className="text-sm text-muted-foreground">Distance: {results.distance}</p>
                    </div>

                    {/* Route Line */}
                    <div className="absolute top-1/2 left-1/4 right-1/4 h-0.5 bg-primary/30 transform -translate-y-1/2" />
                    <div className="absolute top-1/2 left-1/4 w-2 h-2 bg-primary rounded-full transform -translate-x-1/2 -translate-y-1/2" />
                    <div className="absolute top-1/2 right-1/4 w-2 h-2 bg-primary rounded-full transform translate-x-1/2 -translate-y-1/2" />
                  </div>
                </CardContent>
              </Card>
            </motion.div>
          )}

          {/* Route Options */}
          {results && (
            <motion.div
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ duration: 0.6, delay: 0.3 }}
              className="space-y-4"
            >
              <h2 className="text-xl font-semibold">Travel Options</h2>
              <div className="grid grid-cols-1 gap-4">
                {results.options.map((option, index) => (
                  <Card key={index} className={`shadow-elegant border ${getRouteColor(option.type)}`}>
                    <CardContent className="p-6">
                      <div className="flex items-center justify-between">
                        <div className="flex items-center space-x-4">
                          <div className={`w-12 h-12 rounded-lg bg-background flex items-center justify-center ${getRouteIconColor(option.type)}`}>
                            <option.icon className="w-6 h-6" />
                          </div>
                          <div>
                            <h3 className="font-semibold capitalize text-lg">{option.type}</h3>
                            <p className="text-sm text-muted-foreground">{option.details}</p>
                          </div>
                        </div>

                        <div className="text-right">
                          <div className="flex items-center space-x-6">
                            <div className="text-center">
                              <div className="flex items-center space-x-1 text-muted-foreground mb-1">
                                <Clock className="w-4 h-4" />
                                <span className="text-xs">Duration</span>
                              </div>
                              <p className="font-semibold">{option.duration}</p>
                            </div>

                            <div className="text-center">
                              <div className="flex items-center space-x-1 text-muted-foreground mb-1">
                                <DollarSign className="w-4 h-4" />
                                <span className="text-xs">Cost</span>
                              </div>
                              <p className="font-semibold">{option.cost}</p>
                            </div>

                            <div className="text-center">
                              <div className="text-xs text-muted-foreground mb-1">CO₂ Emissions</div>
                              <p className="text-sm font-medium">{option.emissions}</p>
                            </div>
                          </div>
                        </div>
                      </div>
                    </CardContent>
                  </Card>
                ))}
              </div>
            </motion.div>
          )}

          {/* No Results State */}
          {!results && !isSearching && (
            <motion.div
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              transition={{ duration: 0.6 }}
              className="text-center py-12"
            >
              <MapPin className="w-16 h-16 text-muted-foreground mx-auto mb-4" />
              <p className="text-muted-foreground">
                Enter your origin and destination to find the best travel routes
              </p>
            </motion.div>
          )}
        </div>
      </div>
    </div>
  );
}

client/src/pages/SearchFilter.tsx.content:
import { useState } from "react";
import { useQuery } from "@tanstack/react-query";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Badge } from "@/components/ui/badge";
import { Search, MapPin, Calendar, DollarSign, Filter, Loader2 } from "lucide-react";
import { type Trip, type TripFilterData } from "@shared/schema";
import { apiRequest } from "@/lib/queryClient";
import { useToast } from "@/hooks/use-toast";

export default function SearchFilter() {
  const [filters, setFilters] = useState<TripFilterData>({
    country: "",
    minPrice: undefined,
    maxPrice: undefined,
    minDuration: undefined,
    maxDuration: undefined,
    tags: [],
  });
  const [searchResults, setSearchResults] = useState<Trip[]>([]);
  const [isSearching, setIsSearching] = useState(false);
  const [hasSearched, setHasSearched] = useState(false);
  const [selectedTag, setSelectedTag] = useState("");
  const { toast } = useToast();

  const { data: allTrips, isLoading: isLoadingTrips } = useQuery({
    queryKey: ["/api/trips"],
  });

  const searchTrips = async () => {
    setIsSearching(true);
    try {
      // Build filter data, removing empty values
      const filterData: TripFilterData = {};
      if (filters.country?.trim()) filterData.country = filters.country.trim();
      if (filters.minPrice !== undefined && filters.minPrice > 0) filterData.minPrice = filters.minPrice;
      if (filters.maxPrice !== undefined && filters.maxPrice > 0) filterData.maxPrice = filters.maxPrice;
      if (filters.minDuration !== undefined && filters.minDuration > 0) filterData.minDuration = filters.minDuration;
      if (filters.maxDuration !== undefined && filters.maxDuration > 0) filterData.maxDuration = filters.maxDuration;
      if (filters.tags && filters.tags.length > 0) filterData.tags = filters.tags;

      const response = await apiRequest("/api/trips/filter", "POST", filterData);
      setSearchResults(response.data || []);
      setHasSearched(true);
    } catch (error: any) {
      toast({
        title: "Search Failed",
        description: error.message || "Unable to filter trips.",
        variant: "destructive",
      });
      setSearchResults([]);
    } finally {
      setIsSearching(false);
    }
  };

  const clearFilters = () => {
    setFilters({
      country: "",
      minPrice: undefined,
      maxPrice: undefined,
      minDuration: undefined,
      maxDuration: undefined,
      tags: [],
    });
    setSelectedTag("");
    setSearchResults([]);
    setHasSearched(false);
  };

  const addTag = (tag: string) => {
    if (tag && !filters.tags?.includes(tag)) {
      setFilters({
        ...filters,
        tags: [...(filters.tags || []), tag],
      });
      setSelectedTag("");
    }
  };

  const removeTag = (tagToRemove: string) => {
    setFilters({
      ...filters,
      tags: filters.tags?.filter(tag => tag !== tagToRemove) || [],
    });
  };

  const displayTrips = hasSearched ? searchResults : ((allTrips as any)?.data || []);
  const isLoading = isLoadingTrips || isSearching;

  // Common travel tags for quick selection
  const commonTags = [
    "adventure", "beach", "mountain", "culture", "food", "nature", 
    "luxury", "budget", "family", "romance", "wildlife", "historical",
    "city", "desert", "tropical", "winter", "summer"
  ];

  return (
    <div className="min-h-screen bg-gradient-to-br from-purple-50 to-pink-100 dark:from-gray-900 dark:to-gray-800 p-4">
      <div className="max-w-7xl mx-auto">
        {/* Header */}
        <div className="text-center mb-8">
          <h1 className="text-4xl font-bold text-gray-800 dark:text-white mb-2">
            Search & Filter Trips
          </h1>
          <p className="text-gray-600 dark:text-gray-300">
            Find your perfect adventure with our advanced search filters
          </p>
        </div>

        <div className="grid lg:grid-cols-4 gap-6">
          {/* Filters Sidebar */}
          <div className="lg:col-span-1">
            <Card className="sticky top-4">
              <CardHeader>
                <CardTitle className="flex items-center gap-2">
                  <Filter className="h-5 w-5" />
                  Filters
                </CardTitle>
                <CardDescription>
                  Refine your search results
                </CardDescription>
              </CardHeader>
              <CardContent className="space-y-6">
                {/* Country Filter */}
                <div>
                  <label className="text-sm font-medium mb-2 block">Country/Location</label>
                  <Input
                    placeholder="e.g., India, USA, Japan"
                    value={filters.country || ""}
                    onChange={(e) => setFilters({ ...filters, country: e.target.value })}
                  />
                </div>

                {/* Price Range */}
                <div>
                  <label className="text-sm font-medium mb-2 block">Price Range ($)</label>
                  <div className="grid grid-cols-2 gap-2">
                    <Input
                      placeholder="Min"
                      type="number"
                      min="0"
                      value={filters.minPrice || ""}
                      onChange={(e) => setFilters({ 
                        ...filters, 
                        minPrice: e.target.value ? parseFloat(e.target.value) : undefined 
                      })}
                    />
                    <Input
                      placeholder="Max"
                      type="number"
                      min="0"
                      value={filters.maxPrice || ""}
                      onChange={(e) => setFilters({ 
                        ...filters, 
                        maxPrice: e.target.value ? parseFloat(e.target.value) : undefined 
                      })}
                    />
                  </div>
                </div>

                {/* Duration Filter */}
                <div>
                  <label className="text-sm font-medium mb-2 block">Duration (Days)</label>
                  <div className="grid grid-cols-2 gap-2">
                    <Input
                      placeholder="Min"
                      type="number"
                      min="1"
                      value={filters.minDuration || ""}
                      onChange={(e) => setFilters({ 
                        ...filters, 
                        minDuration: e.target.value ? parseInt(e.target.value) : undefined 
                      })}
                    />
                    <Input
                      placeholder="Max"
                      type="number"
                      min="1"
                      value={filters.maxDuration || ""}
                      onChange={(e) => setFilters({ 
                        ...filters, 
                        maxDuration: e.target.value ? parseInt(e.target.value) : undefined 
                      })}
                    />
                  </div>
                </div>

                {/* Tag Filter */}
                <div>
                  <label className="text-sm font-medium mb-2 block">Trip Type</label>
                  <Select value={selectedTag} onValueChange={addTag}>
                    <SelectTrigger>
                      <SelectValue placeholder="Select a tag..." />
                    </SelectTrigger>
                    <SelectContent>
                      {commonTags.map((tag) => (
                        <SelectItem key={tag} value={tag}>
                          {tag}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>

                  {/* Selected Tags */}
                  {filters.tags && filters.tags.length > 0 && (
                    <div className="flex flex-wrap gap-1 mt-2">
                      {filters.tags.map((tag) => (
                        <Badge 
                          key={tag} 
                          variant="secondary" 
                          className="cursor-pointer"
                          onClick={() => removeTag(tag)}
                        >
                          {tag} ×
                        </Badge>
                      ))}
                    </div>
                  )}
                </div>

                {/* Action Buttons */}
                <div className="space-y-2">
                  <Button 
                    onClick={searchTrips}
                    disabled={isSearching}
                    className="w-full"
                  >
                    {isSearching ? (
                      <>
                        <Loader2 className="h-4 w-4 mr-2 animate-spin" />
                        Searching...
                      </>
                    ) : (
                      <>
                        <Search className="h-4 w-4 mr-2" />
                        Apply Filters
                      </>
                    )}
                  </Button>

                  <Button 
                    variant="outline" 
                    onClick={clearFilters}
                    className="w-full"
                  >
                    Clear All Filters
                  </Button>
                </div>

                {/* Filter Summary */}
                <div className="text-sm text-gray-600 dark:text-gray-400 pt-2 border-t">
                  {hasSearched ? (
                    <>Showing {searchResults.length} filtered results</>
                  ) : (
                    <>Showing all {(allTrips as any)?.data?.length || 0} trips</>
                  )}
                </div>
              </CardContent>
            </Card>
          </div>

          {/* Results Grid */}
          <div className="lg:col-span-3">
            {isLoading ? (
              <div className="grid md:grid-cols-2 lg:grid-cols-3 gap-6">
                {[...Array(6)].map((_, i) => (
                  <Card key={i} className="animate-pulse">
                    <div className="h-48 bg-gray-200 dark:bg-gray-700"></div>
                    <CardContent className="p-4">
                      <div className="h-4 bg-gray-200 dark:bg-gray-700 rounded mb-2"></div>
                      <div className="h-4 bg-gray-200 dark:bg-gray-700 rounded w-2/3"></div>
                    </CardContent>
                  </Card>
                ))}
              </div>
            ) : displayTrips.length === 0 ? (
              <Card>
                <CardContent className="py-12 text-center">
                  <Search className="h-12 w-12 mx-auto mb-4 text-gray-400" />
                  <h3 className="text-lg font-semibold mb-2">
                    {hasSearched ? "No trips found" : "No trips available"}
                  </h3>
                  <p className="text-gray-600 dark:text-gray-400">
                    {hasSearched 
                      ? "Try adjusting your filters to see more results"
                      : "There are currently no trips available"
                    }
                  </p>
                </CardContent>
              </Card>
            ) : (
              <div className="grid md:grid-cols-2 lg:grid-cols-3 gap-6">
                {displayTrips.map((trip: Trip) => (
                  <Card key={trip.id} className="overflow-hidden hover:shadow-lg transition-shadow">
                    {trip.imageUrl && (
                      <div className="h-48 bg-gray-200 dark:bg-gray-700">
                        <img
                          src={trip.imageUrl}
                          alt={trip.title}
                          className="w-full h-full object-cover"
                          onError={(e) => {
                            e.currentTarget.style.display = 'none';
                          }}
                        />
                      </div>
                    )}
                    <CardContent className="p-4">
                      <div className="flex justify-between items-start mb-3">
                        <h3 className="font-bold text-lg line-clamp-2">{trip.title}</h3>
                        <div className="text-right">
                          <div className="text-xl font-bold text-blue-600 dark:text-blue-400">
                            ${parseFloat(trip.price).toLocaleString()}
                          </div>
                          <div className="text-xs text-gray-500">per person</div>
                        </div>
                      </div>

                      <div className="flex items-center gap-2 mb-3 text-gray-600 dark:text-gray-400">
                        <MapPin className="h-4 w-4" />
                        <span className="text-sm">{trip.location}</span>
                      </div>

                      <div className="flex items-center gap-4 mb-4 text-sm text-gray-600 dark:text-gray-400">
                        <div className="flex items-center gap-1">
                          <Calendar className="h-4 w-4" />
                          <span>{trip.duration} days</span>
                        </div>
                      </div>

                      {trip.description && (
                        <p className="text-gray-600 dark:text-gray-400 text-sm mb-4 line-clamp-3">
                          {trip.description}
                        </p>
                      )}

                      {trip.tags && trip.tags.length > 0 && (
                        <div className="flex flex-wrap gap-1 mb-4">
                          {trip.tags.slice(0, 3).map((tag) => (
                            <Badge key={tag} variant="outline" className="text-xs">
                              {tag}
                            </Badge>
                          ))}
                          {trip.tags.length > 3 && (
                            <Badge variant="secondary" className="text-xs">
                              +{trip.tags.length - 3} more
                            </Badge>
                          )}
                        </div>
                      )}

                      <Button className="w-full" size="sm">
                        View Details
                      </Button>
                    </CardContent>
                  </Card>
                ))}
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

client/src/pages/Signup.tsx.content:
import { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { motion } from 'framer-motion';
import { Eye, EyeOff, Mail, Lock, User, ArrowLeft } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Card, CardContent } from '@/components/ui/card';
import { LoadingSpinner } from '@/components/ui/loading-spinner';
import { useAuth } from '@/hooks/use-auth';
import { useToast } from '@/hooks/use-toast';

export default function Signup() {
  const [formData, setFormData] = useState({
    name: '',
    email: '',
    password: '',
    confirmPassword: ''
  });
  const [showPassword, setShowPassword] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const { register } = useAuth();
  const { toast } = useToast();
  const navigate = useNavigate();

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setFormData(prev => ({
      ...prev,
      [e.target.name]: e.target.value
    }));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (formData.password !== formData.confirmPassword) {
      toast({
        title: "Error",
        description: "Passwords do not match.",
        variant: "destructive",
      });
      return;
    }

    setIsLoading(true);

    try {
      await register(formData.name, formData.email, formData.password);

      toast({
        title: "Welcome to ExploreNow!",
        description: "Your account has been created successfully.",
      });
      navigate('/');
    } catch (error) {
      toast({
        title: "Error",
        description: error instanceof Error ? error.message : "Failed to create account. Please try again.",
        variant: "destructive",
      });
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-gradient-linear flex items-center justify-center p-6">
      <motion.div
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.6 }}
        className="w-full max-w-md"
      >
        <div className="mb-8">
          <Link
            to="/"
            className="inline-flex items-center text-sm text-muted-foreground hover:text-foreground transition-colors mb-6"
          >
            <ArrowLeft className="w-4 h-4 mr-2" />
            Back to Home
          </Link>
          <h1 className="text-heading mb-2">Create Account</h1>
          <p className="text-body text-muted-foreground">
            Start your journey with ExploreNow
          </p>
        </div>

        <Card className="border-0 shadow-elegant-lg">
          <CardContent className="p-8">
            <form onSubmit={handleSubmit} className="space-y-6">
              <div className="space-y-2">
                <label htmlFor="name" className="text-sm font-medium">
                  Full Name
                </label>
                <div className="relative">
                  <User className="absolute left-3 top-1/2 transform -translate-y-1/2 w-4 h-4 text-muted-foreground" />
                  <Input
                    id="name"
                    name="name"
                    type="text"
                    value={formData.name}
                    onChange={handleChange}
                    className="pl-10"
                    placeholder="Your full name"
                    required
                    disabled={isLoading}
                  />
                </div>
              </div>

              <div className="space-y-2">
                <label htmlFor="email" className="text-sm font-medium">
                  Email Address
                </label>
                <div className="relative">
                  <Mail className="absolute left-3 top-1/2 transform -translate-y-1/2 w-4 h-4 text-muted-foreground" />
                  <Input
                    id="email"
                    name="email"
                    type="email"
                    value={formData.email}
                    onChange={handleChange}
                    className="pl-10"
                    placeholder="your@email.com"
                    required
                    disabled={isLoading}
                  />
                </div>
              </div>

              <div className="space-y-2">
                <label htmlFor="password" className="text-sm font-medium">
                  Password
                </label>
                <div className="relative">
                  <Lock className="absolute left-3 top-1/2 transform -translate-y-1/2 w-4 h-4 text-muted-foreground" />
                  <Input
                    id="password"
                    name="password"
                    type={showPassword ? 'text' : 'password'}
                    value={formData.password}
                    onChange={handleChange}
                    className="pl-10 pr-10"
                    placeholder="Create a password"
                    required
                    disabled={isLoading}
                  />
                  <button
                    type="button"
                    onClick={() => setShowPassword(!showPassword)}
                    className="absolute right-3 top-1/2 transform -translate-y-1/2 text-muted-foreground hover:text-foreground"
                    disabled={isLoading}
                  >
                    {showPassword ? <EyeOff className="w-4 h-4" /> : <Eye className="w-4 h-4" />}
                  </button>
                </div>
              </div>

              <div className="space-y-2">
                <label htmlFor="confirmPassword" className="text-sm font-medium">
                  Confirm Password
                </label>
                <div className="relative">
                  <Lock className="absolute left-3 top-1/2 transform -translate-y-1/2 w-4 h-4 text-muted-foreground" />
                  <Input
                    id="confirmPassword"
                    name="confirmPassword"
                    type="password"
                    value={formData.confirmPassword}
                    onChange={handleChange}
                    className="pl-10"
                    placeholder="Confirm your password"
                    required
                    disabled={isLoading}
                  />
                </div>
              </div>

              <Button
