import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { useLocation } from "wouter";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Form, FormControl, FormField, FormItem, FormLabel, FormMessage } from "@/components/ui/form";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Badge } from "@/components/ui/badge";
import { MapPin, Calendar, Plus, X, Plane } from "lucide-react";
import { insertTripSchema, type InsertTrip, type Hotel } from "@shared/schema";
import { useToast } from "@/hooks/use-toast";
import { apiRequest } from "@/lib/queryClient";
import { useState } from "react";
import { useAuth } from "@/hooks/use-auth";

export default function TripSubmission() {
  const [, navigate] = useLocation();
  const { user } = useAuth();
  const { toast } = useToast();
  const queryClient = useQueryClient();
  const [tags, setTags] = useState<string[]>([]);
  const [includes, setIncludes] = useState<string[]>([]);
  const [newTag, setNewTag] = useState("");
  const [newInclude, setNewInclude] = useState("");

  const form = useForm<InsertTrip>({
    resolver: zodResolver(insertTripSchema),
    defaultValues: {
      duration: 3,
      tags: [],
      includes: [],
    },
  });

  // Fetch hotels for selection
  const { data: hotels } = useQuery({
    queryKey: ["/api/hotels"],
  });

  // Check if user is admin
  if (!user || user.role !== "admin") {
    return (
      <div className="min-h-screen bg-gray-50 dark:bg-gray-900 flex items-center justify-center">
        <Card className="w-full max-w-md">
          <CardHeader>
            <CardTitle className="text-center text-red-600">Access Denied</CardTitle>
            <CardDescription className="text-center">
              Only administrators can submit trips. Please log in as an admin.
            </CardDescription>
          </CardHeader>
          <CardContent>
            <Button 
              onClick={() => navigate("/login")} 
              className="w-full"
            >
              Go to Login
            </Button>
          </CardContent>
        </Card>
      </div>
    );
  }

  const createTripMutation = useMutation({
    mutationFn: (data: InsertTrip) => apiRequest("/api/trips", "POST", data),
    onSuccess: () => {
      toast({
        title: "Trip Created!",
        description: "The trip has been successfully added to the platform.",
      });
      queryClient.invalidateQueries({ queryKey: ["/api/trips"] });
      navigate("/admin");
    },
    onError: (error: any) => {
      toast({
        title: "Creation Failed",
        description: error.message || "There was an error creating the trip.",
        variant: "destructive",
      });
    },
  });

  const onSubmit = (data: InsertTrip) => {
    const tripData = {
      ...data,
      tags,
      includes,
    };
    createTripMutation.mutate(tripData);
  };

  const addTag = () => {
    if (newTag.trim() && !tags.includes(newTag.trim())) {
      setTags([...tags, newTag.trim()]);
      setNewTag("");
    }
  };

  const removeTag = (tagToRemove: string) => {
    setTags(tags.filter(tag => tag !== tagToRemove));
  };

  const addInclude = () => {
    if (newInclude.trim() && !includes.includes(newInclude.trim())) {
      setIncludes([...includes, newInclude.trim()]);
      setNewInclude("");
    }
  };

  const removeInclude = (includeToRemove: string) => {
    setIncludes(includes.filter(include => include !== includeToRemove));
  };

  // Predefined tag suggestions
  const commonTags = [
    "adventure", "beach", "mountain", "culture", "food", "nature", 
    "luxury", "budget", "family", "romance", "wildlife", "historical"
  ];

  const commonIncludes = [
    "Accommodation", "Meals", "Transport", "Guide", "Activities", 
    "Insurance", "Airport Transfer", "Sightseeing"
  ];

  return (
    <div className="min-h-screen bg-gradient-to-br from-green-50 to-emerald-100 dark:from-gray-900 dark:to-gray-800 p-4">
      <div className="max-w-4xl mx-auto">
        {/* Header */}
        <div className="text-center mb-8">
          <h1 className="text-4xl font-bold text-gray-800 dark:text-white mb-2">
            Create New Trip
          </h1>
          <p className="text-gray-600 dark:text-gray-300">
            Add an exciting new travel destination for adventurers to explore
          </p>
        </div>

        <Card>
          <CardHeader>
            <CardTitle className="flex items-center gap-2">
              <Plane className="h-5 w-5" />
              Trip Information
            </CardTitle>
            <CardDescription>
              Fill in the details about the trip you want to create
            </CardDescription>
          </CardHeader>
          <CardContent>
            <Form {...form}>
              <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-6">
                {/* Basic Information */}
                <div className="grid md:grid-cols-2 gap-4">
                  <FormField
                    control={form.control}
                    name="title"
                    render={({ field }) => (
                      <FormItem>
                        <FormLabel>Trip Title</FormLabel>
                        <FormControl>
                          <Input placeholder="Amazing Bali Adventure" {...field} />
                        </FormControl>
                        <FormMessage />
                      </FormItem>
                    )}
                  />

                  <FormField
                    control={form.control}
                    name="location"
                    render={({ field }) => (
                      <FormItem>
                        <FormLabel>Destination</FormLabel>
                        <FormControl>
                          <Input placeholder="Bali, Indonesia" {...field} />
                        </FormControl>
                        <FormMessage />
                      </FormItem>
                    )}
                  />
                </div>

                <FormField
                  control={form.control}
                  name="description"
                  render={({ field }) => (
                    <FormItem>
                      <FormLabel>Description</FormLabel>
                      <FormControl>
                        <Textarea
                          placeholder="Describe the trip, what travelers will experience, and what makes it special..."
                          className="resize-none"
                          rows={4}
                          {...field}
                        />
                      </FormControl>
                      <FormMessage />
                    </FormItem>
                  )}
                />

                {/* Pricing and Duration */}
                <div className="grid md:grid-cols-3 gap-4">
                  <FormField
                    control={form.control}
                    name="price"
                    render={({ field }) => (
                      <FormItem>
                        <FormLabel>Price per Person ($)</FormLabel>
                        <FormControl>
                          <Input type="number" step="0.01" placeholder="999.99" {...field} />
                        </FormControl>
                        <FormMessage />
                      </FormItem>
                    )}
                  />

                  <FormField
                    control={form.control}
                    name="duration"
                    render={({ field }) => (
                      <FormItem>
                        <FormLabel>Duration (Days)</FormLabel>
                        <FormControl>
                          <Input 
                            type="number" 
                            min="1" 
                            max="30" 
                            placeholder="7" 
                            {...field}
                            onChange={(e) => field.onChange(parseInt(e.target.value))}
                          />
                        </FormControl>
                        <FormMessage />
                      </FormItem>
                    )}
                  />

                  <FormField
                    control={form.control}
                    name="imageUrl"
                    render={({ field }) => (
                      <FormItem>
                        <FormLabel>Cover Image URL</FormLabel>
                        <FormControl>
                          <Input placeholder="https://example.com/image.jpg" {...field} />
                        </FormControl>
                        <FormMessage />
                      </FormItem>
                    )}
                  />
                </div>

                {/* Tags */}
                <div className="space-y-3">
                  <FormLabel>Trip Tags</FormLabel>
                  <div className="flex gap-2">
                    <Input
                      placeholder="Add a tag..."
                      value={newTag}
                      onChange={(e) => setNewTag(e.target.value)}
                      onKeyPress={(e) => e.key === "Enter" && (e.preventDefault(), addTag())}
                    />
                    <Button type="button" onClick={addTag} size="sm">
                      <Plus className="h-4 w-4" />
                    </Button>
                  </div>

                  {/* Common tags */}
                  <div className="space-y-2">
                    <p className="text-sm text-gray-600 dark:text-gray-400">Quick add:</p>
                    <div className="flex flex-wrap gap-2">
                      {commonTags.map((tag) => (
                        <Badge 
                          key={tag} 
                          variant="outline" 
                          className="cursor-pointer hover:bg-primary hover:text-primary-foreground"
                          onClick={() => {
                            if (!tags.includes(tag)) {
                              setTags([...tags, tag]);
                            }
                          }}
                        >
                          {tag}
                        </Badge>
                      ))}
                    </div>
                  </div>

                  <div className="flex flex-wrap gap-2">
                    {tags.map((tag) => (
                      <Badge key={tag} variant="secondary" className="cursor-pointer">
                        {tag}
                        <X 
                          className="h-3 w-3 ml-1" 
                          onClick={() => removeTag(tag)}
                        />
                      </Badge>
                    ))}
                  </div>
                </div>

                {/* Includes */}
                <div className="space-y-3">
                  <FormLabel>What's Included</FormLabel>
                  <div className="flex gap-2">
                    <Input
                      placeholder="What's included in the trip..."
                      value={newInclude}
                      onChange={(e) => setNewInclude(e.target.value)}
                      onKeyPress={(e) => e.key === "Enter" && (e.preventDefault(), addInclude())}
                    />
                    <Button type="button" onClick={addInclude} size="sm">
                      <Plus className="h-4 w-4" />
                    </Button>
                  </div>

                  {/* Common includes */}
                  <div className="space-y-2">
                    <p className="text-sm text-gray-600 dark:text-gray-400">Quick add:</p>
                    <div className="flex flex-wrap gap-2">
                      {commonIncludes.map((include) => (
                        <Badge 
                          key={include} 
                          variant="outline" 
                          className="cursor-pointer hover:bg-primary hover:text-primary-foreground"
                          onClick={() => {
                            if (!includes.includes(include)) {
                              setIncludes([...includes, include]);
                            }
                          }}
                        >
                          {include}
                        </Badge>
                      ))}
                    </div>
                  </div>

                  <div className="flex flex-wrap gap-2">
                    {includes.map((include) => (
                      <Badge key={include} variant="default" className="cursor-pointer">
                        {include}
                        <X 
                          className="h-3 w-3 ml-1" 
                          onClick={() => removeInclude(include)}
                        />
                      </Badge>
                    ))}
                  </div>
                </div>

                {/* Trip Preview */}
                {form.watch("title") && (
                  <div className="bg-gray-50 dark:bg-gray-800 p-4 rounded-lg border">
                    <h3 className="font-semibold mb-2">Trip Preview</h3>
                    <div className="space-y-2 text-sm">
                      <p><strong>Title:</strong> {form.watch("title")}</p>
                      <p><strong>Location:</strong> {form.watch("location")}</p>
                      <p><strong>Duration:</strong> {form.watch("duration")} days</p>
                      <p><strong>Price:</strong> ${form.watch("price")}</p>
                      {tags.length > 0 && (
                        <p><strong>Tags:</strong> {tags.join(", ")}</p>
                      )}
                    </div>
                  </div>
                )}

                {/* Submit Button */}
                <div className="flex gap-4 pt-4">
                  <Button 
                    type="button" 
                    variant="outline" 
                    onClick={() => navigate("/admin")}
                    className="flex-1"
                  >
                    Cancel
                  </Button>
                  <Button 
                    type="submit" 
                    disabled={createTripMutation.isPending}
                    className="flex-1"
                  >
                    {createTripMutation.isPending ? "Creating..." : "Create Trip"}
                  </Button>
                </div>
              </form>
            </Form>
          </CardContent>
        </Card>
      </div>
    </div>
  );
}

client/src/pages/TripSuggestionByBudget..content:
import { useState } from "react";
import { useQuery } from "@tanstack/react-query";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { DollarSign, Search, MapPin, Calendar, Star, Users } from "lucide-react";
import { type Trip } from "@shared/schema";
import { apiRequest } from "@/lib/queryClient";
import { useToast } from "@/hooks/use-toast";

export default function TripSuggestionByBudget() {
  const [budget, setBudget] = useState("");
  const [currency, setCurrency] = useState("USD");
  const [searchResults, setSearchResults] = useState<Trip[]>([]);
  const [isSearching, setIsSearching] = useState(false);
  const [hasSearched, setHasSearched] = useState(false);
  const { toast } = useToast();

  const { data: allTrips } = useQuery({
    queryKey: ["/api/trips"],
  });

  const searchByBudget = async () => {
    if (!budget || parseFloat(budget) <= 0) {
      toast({
        title: "Invalid Budget",
        description: "Please enter a valid budget amount.",
        variant: "destructive",
      });
      return;
    }

    setIsSearching(true);
    try {
      const response = await apiRequest("/api/trips/budget", "POST", {
        budget: parseFloat(budget),
        currency,
      });
      setSearchResults(response.data || []);
      setHasSearched(true);
    } catch (error: any) {
      toast({
        title: "Search Failed",
        description: error.message || "Unable to search trips by budget.",
        variant: "destructive",
      });
      setSearchResults([]);
    } finally {
      setIsSearching(false);
    }
  };

  const handleKeyPress = (e: React.KeyboardEvent) => {
    if (e.key === "Enter") {
      searchByBudget();
    }
  };

  const formatPrice = (price: string) => {
    return parseFloat(price).toLocaleString();
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-emerald-50 to-teal-100 dark:from-gray-900 dark:to-gray-800 p-4">
      <div className="max-w-6xl mx-auto">
        {/* Header */}
        <div className="text-center mb-8">
          <h1 className="text-4xl font-bold text-gray-800 dark:text-white mb-2">
            Find Trips by Budget
          </h1>
          <p className="text-gray-600 dark:text-gray-300">
            Discover amazing destinations that fit perfectly within your budget
          </p>
        </div>

        {/* Search Section */}
        <Card className="mb-8">
          <CardHeader>
            <CardTitle className="flex items-center gap-2">
              <DollarSign className="h-5 w-5" />
              Budget Search
            </CardTitle>
            <CardDescription>
              Enter your budget to find trips that match your spending limits
            </CardDescription>
          </CardHeader>
          <CardContent>
            <div className="flex gap-4 items-end">
              <div className="flex-1">
                <label className="text-sm font-medium mb-2 block">
                  Maximum Budget
                </label>
                <Input
                  type="number"
                  placeholder="1000"
                  value={budget}
                  onChange={(e) => setBudget(e.target.value)}
                  onKeyPress={handleKeyPress}
                  min="0"
                  step="10"
                />
              </div>

              <div className="w-24">
                <label className="text-sm font-medium mb-2 block">
                  Currency
                </label>
                <Select value={currency} onValueChange={setCurrency}>
                  <SelectTrigger>
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="USD">USD</SelectItem>
                    <SelectItem value="EUR">EUR</SelectItem>
                    <SelectItem value="GBP">GBP</SelectItem>
                    <SelectItem value="INR">INR</SelectItem>
                    <SelectItem value="JPY">JPY</SelectItem>
                    <SelectItem value="CAD">CAD</SelectItem>
                    <SelectItem value="AUD">AUD</SelectItem>
                  </SelectContent>
                </Select>
              </div>

              <Button 
                onClick={searchByBudget} 
                disabled={isSearching || !budget}
                className="px-8"
              >
                {isSearching ? (
                  "Searching..."
                ) : (
                  <>
                    <Search className="h-4 w-4 mr-2" />
                    Search
                  </>
                )}
              </Button>
            </div>
          </CardContent>
        </Card>

        {/* Budget Tips */}
        <Card className="mb-8 bg-blue-50 dark:bg-blue-900/20 border-blue-200 dark:border-blue-800">
          <CardContent className="pt-6">
            <div className="grid md:grid-cols-3 gap-4 text-sm">
              <div className="text-center">
                <DollarSign className="h-8 w-8 mx-auto mb-2 text-blue-600" />
                <h3 className="font-semibold mb-1">Budget Planning</h3>
                <p className="text-gray-600 dark:text-gray-400">
                  Include accommodation, meals, activities, and transport in your budget
                </p>
              </div>
              <div className="text-center">
                <Calendar className="h-8 w-8 mx-auto mb-2 text-blue-600" />
                <h3 className="font-semibold mb-1">Flexible Dates</h3>
                <p className="text-gray-600 dark:text-gray-400">
                  Travel during off-peak seasons for better deals and lower costs
                </p>
              </div>
              <div className="text-center">
                <MapPin className="h-8 w-8 mx-auto mb-2 text-blue-600" />
                <h3 className="font-semibold mb-1">Local Experiences</h3>
                <p className="text-gray-600 dark:text-gray-400">
                  Consider local destinations to maximize your budget's value
                </p>
              </div>
            </div>
          </CardContent>
        </Card>

        {/* Search Results */}
        {hasSearched && (
          <div>
            <div className="flex justify-between items-center mb-6">
              <h2 className="text-2xl font-bold text-gray-800 dark:text-white">
                Search Results
              </h2>
              <Badge variant="secondary" className="text-lg px-3 py-1">
                {searchResults.length} trip{searchResults.length !== 1 ? 's' : ''} found
              </Badge>
            </div>

            {searchResults.length === 0 ? (
              <Card>
                <CardContent className="py-12 text-center">
                  <div className="text-gray-500 dark:text-gray-400">
                    <MapPin className="h-12 w-12 mx-auto mb-4 opacity-50" />
                    <h3 className="text-lg font-semibold mb-2">No trips found</h3>
                    <p>
                      No trips found within your budget of ${budget}. 
                      Try increasing your budget or check out our affordable options.
                    </p>
                  </div>
                </CardContent>
              </Card>
            ) : (
              <div className="grid md:grid-cols-2 lg:grid-cols-3 gap-6">
                {searchResults.map((trip) => (
                  <Card key={trip.id} className="overflow-hidden hover:shadow-lg transition-shadow">
                    {trip.imageUrl && (
                      <div className="h-48 bg-gray-200 dark:bg-gray-700">
                        <img
                          src={trip.imageUrl}
                          alt={trip.title}
                          className="w-full h-full object-cover"
                          onError={(e) => {
                            e.currentTarget.style.display = 'none';
                          }}
                        />
                      </div>
                    )}
                    <CardContent className="p-6">
                      <div className="flex justify-between items-start mb-3">
                        <h3 className="font-bold text-lg line-clamp-2">{trip.title}</h3>
                        <div className="text-right">
                          <div className="text-2xl font-bold text-green-600 dark:text-green-400">
                            ${formatPrice(trip.price)}
                          </div>
                          <div className="text-xs text-gray-500">per person</div>
                        </div>
                      </div>

                      <div className="flex items-center gap-2 mb-3 text-gray-600 dark:text-gray-400">
                        <MapPin className="h-4 w-4" />
                        <span className="text-sm">{trip.location}</span>
                      </div>

                      <div className="flex items-center gap-4 mb-4 text-sm text-gray-600 dark:text-gray-400">
                        <div className="flex items-center gap-1">
                          <Calendar className="h-4 w-4" />
                          <span>{trip.duration} days</span>
                        </div>
                      </div>

                      {trip.description && (
                        <p className="text-gray-600 dark:text-gray-400 text-sm mb-4 line-clamp-3">
                          {trip.description}
                        </p>
                      )}

                      {trip.tags && trip.tags.length > 0 && (
                        <div className="flex flex-wrap gap-1 mb-4">
                          {trip.tags.slice(0, 3).map((tag) => (
                            <Badge key={tag} variant="outline" className="text-xs">
                              {tag}
                            </Badge>
                          ))}
                          {trip.tags.length > 3 && (
                            <Badge variant="secondary" className="text-xs">
                              +{trip.tags.length - 3} more
                            </Badge>
                          )}
                        </div>
                      )}

                      <div className="space-y-2">
                        <Button className="w-full" size="sm">
                          View Details
                        </Button>
                        <div className="text-center">
                          <Badge 
                            variant="secondary" 
                            className="text-green-700 bg-green-100 dark:bg-green-900 dark:text-green-300"
                          >
                            Within Budget
                          </Badge>
                        </div>
                      </div>
                    </CardContent>
                  </Card>
                ))}
              </div>
            )}
          </div>
        )}

        {/* All Trips Preview */}
        {!hasSearched && allTrips?.data && (
          <div>
            <h2 className="text-2xl font-bold text-gray-800 dark:text-white mb-6">
              All Available Trips
            </h2>
            <div className="grid md:grid-cols-2 lg:grid-cols-3 gap-6">
              {allTrips.data.slice(0, 6).map((trip: Trip) => (
                <Card key={trip.id} className="overflow-hidden">
                  {trip.imageUrl && (
                    <div className="h-32 bg-gray-200 dark:bg-gray-700">
                      <img
                        src={trip.imageUrl}
                        alt={trip.title}
                        className="w-full h-full object-cover"
                        onError={(e) => {
                          e.currentTarget.style.display = 'none';
                        }}
                      />
                    </div>
                  )}
                  <CardContent className="p-4">
                    <h3 className="font-semibold mb-2 line-clamp-1">{trip.title}</h3>
                    <div className="flex justify-between items-center">
                      <span className="text-sm text-gray-600 dark:text-gray-400">
                        {trip.location}
                      </span>
                      <span className="font-bold text-lg text-blue-600">
                        ${formatPrice(trip.price)}
                      </span>
                    </div>
                  </CardContent>
                </Card>
              ))}
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

