  canonicalUrl = "https://explorenow.replit.app/",
  ogTitle,
  ogDescription,
  ogImage = "/og-image.png",
  ogType = "website"
}: SEOHeadProps) {
  return (
    <Helmet>
      <title>{title}</title>
      <meta name="description" content={description} />
      <meta name="keywords" content={keywords} />
