        </div>
      </SelectTrigger>
      <SelectContent>
        {currencies.map((curr) => (
          <SelectItem key={curr.code} value={curr.code}>
            <div className="flex items-center space-x-2">
              <span className="font-medium">{curr.symbol}</span>
              <span>{curr.name}</span>
              <span className="text-muted-foreground">({curr.code})</span>
            </div>
          </SelectItem>
        ))}
      </SelectContent>
    </Select>
  );
};

